UPDATE products
SET category_tags = CASE
  WHEN category_tags IS NULL OR TRIM(category_tags) = '' THEN 'Gluten Free sauces'
  WHEN CONCAT(',', category_tags, ',') LIKE '%,Gluten Free sauces,%' THEN category_tags
  ELSE CONCAT(category_tags, ',', 'Gluten Free sauces')
END
WHERE barcode = '0008295663900';

