-- Remove incorrect breakfast-cereal substitute tag from tahini spread (not a cereal).
UPDATE products
SET category_tags = TRIM(BOTH ',' FROM REPLACE(CONCAT(',', category_tags, ','), ',Gluten free Breakfast cereals,', ','))
WHERE barcode = '8888536703136'
  AND CONCAT(',', category_tags, ',') LIKE '%,Gluten free Breakfast cereals,%';

